export function ContactSection({
  heading = "{{heading}}",
  phone = "{{phone}}",
  email = "{{email}}",
  layout = "{{layout}}",
  showMap = {{showMap}},
}) {
  return (
    <section style={{ display: "flex", gap: 28, flexDirection: layout === "stacked" ? "column" : "row",
      font: "16px/1.5 system-ui, sans-serif", color: "#241430", padding: 24, background: "#FAF7F2" }}>
      <div style={{ flex: "1 1 260px" }}>
        <h2 style={{ margin: "0 0 12px", fontSize: 24, fontWeight: 700 }}>{heading}</h2>
        <p><a href={`tel:${phone}`} style={{ color: "#241430" }}>{phone}</a></p>
        <p><a href={`mailto:${email}`} style={{ color: "#241430" }}>{email}</a></p>
        <form style={{ display: "flex", flexDirection: "column", gap: 6, marginTop: 16, maxWidth: 320 }}>
          <label htmlFor="contact-name" style={{ fontSize: 13, fontWeight: 600 }}>Name</label>
          <input id="contact-name" type="text" name="name" style={{ font: "inherit", padding: "8px 10px", border: "1px solid #24143033", borderRadius: 8 }} />
          <label htmlFor="contact-message" style={{ fontSize: 13, fontWeight: 600 }}>Message</label>
          <textarea id="contact-message" name="message" rows={3} style={{ font: "inherit", padding: "8px 10px", border: "1px solid #24143033", borderRadius: 8 }} />
          <button type="submit" style={{ alignSelf: "flex-start", marginTop: 6, background: "#241430", color: "#FAF7F2",
            border: "none", padding: "10px 18px", borderRadius: 8, fontWeight: 600, cursor: "pointer" }}>Send message</button>
        </form>
      </div>
      {showMap && (
        <div role="img" aria-label="Map showing business location" style={{ flex: "1 1 260px", minHeight: 200,
          borderRadius: 12, background: "repeating-linear-gradient(45deg, #24143012, #24143012 10px, #24143008 10px, #24143008 20px)" }} />
      )}
    </section>
  );
}
